const portfolioShowPage=showPage;
const dashNav=document.querySelector('#dashNav');
dashNav.insertAdjacentHTML('afterend','<div id="performanceNav" class="dashnav" role="button" tabindex="0" onclick="showPage(\'performance\')" onkeydown="if(event.key===\'Enter\')showPage(\'performance\')">▤ &nbsp;월별 실적 입력</div>');
document.querySelector('#dashboardPage').insertAdjacentHTML('afterend',`<main id="performancePage" class="main" hidden><div class="top"><div><div class="eyebrow">MONTHLY REPORTING</div><h1>월별 실적 입력</h1><p>각 월말까지 달성한 누적 진척률을 보고하세요.</p></div><button class="secondary" onclick="showPage('list')">전체 과제 보기</button></div><div class="banner">시연 화면 · 이 브라우저에만 저장됩니다. 담당자 자동 알림은 연동 전입니다.</div><section class="panel"><h2>보고할 과제 선택</h2><div class="field"><label for="performanceSelect">과제</label><select id="performanceSelect" onchange="selectPerformance(this.value)"></select></div><div id="performanceContent"></div></section></main>`);
let performanceDraft={},performanceId='',reportYear=Number(PlanModel.today().slice(0,4));
showPage=function(page){document.querySelector('#registrationPage').hidden=page!=='registration';document.querySelector('#performancePage').hidden=page!=='performance';document.querySelector('#performanceNav').classList.toggle('selected',page==='performance');portfolioShowPage(page);if(page==='performance')populatePerformance()};
function populatePerformance(selected){const sel=document.querySelector('#performanceSelect');sel.innerHTML='<option value="">과제를 선택하세요</option>'+data.filter(x=>!x.archivedAt).map(x=>`<option value="${esc(x.id)}">${esc(x.title)} · ${esc(x.team||'팀 미지정')}</option>`).join('');if(selected)sel.value=selected;selectPerformance(sel.value)}
function selectPerformance(id){performanceId=id;reportYear=Number(PlanModel.today().slice(0,4));const x=data.find(a=>a.id===id),box=document.querySelector('#performanceContent');if(!x||x.archivedAt){box.innerHTML='<div class="empty">과제를 선택하면 월별 실적 입력표가 표시됩니다.</div>';return}if(x.planMode!=='cumulative-percent-v1'||PlanModel.validatePlan(x).length){box.innerHTML='<div class="legacy-note">먼저 과제 기간과 누적 진척률 기준의 목표 계획을 확인해 주세요.</div><div class="actions"><button type="button" class="primary" id="reportPlanEdit">목표 계획 등록 / 수정</button></div>';document.querySelector('#reportPlanEdit').onclick=()=>openForm(id);return}performanceDraft=copyObject(x.monthly);if(window.StepUI)StepUI.initReport(x);const years=[...new Set([reportYear,...PlanModel.years(x.startDate,x.endDate)])].sort((a,b)=>a-b);box.innerHTML=`<div class="report-info"><div><strong>${esc(x.title)}</strong><p>${esc(x.team||'팀 미지정')} · PM ${esc(x.pm||'미지정')} · ${esc(x.startDate)} ~ ${esc(x.endDate)}</p></div><span id="reportStatus"></span></div><div id="reportErrors" class="form-error-summary" role="alert" hidden></div><div class="annual-toolbar"><div class="annual-year"><label for="reportYear">실적 연도</label><select id="reportYear" onchange="changeReportYear(this.value)">${years.map(y=>`<option value="${y}" ${y===reportYear?'selected':''}>${y}년</option>`).join('')}</select></div><span class="report-help">누적 진척률 % · 미래 월은 입력할 수 없습니다.</span></div><div id="reportGrid"></div><div id="reportPreview" class="annual-feedback"></div><div id="delayReasons"></div><div class="actions"><span>목표 변경은 과제 수정에서 승인 요청할 수 있습니다.</span><button class="primary" onclick="savePerformance()">실적 저장</button></div>`;drawReportGrid();reportPreview()}
function changeReportYear(year){readReport();reportYear=Number(year);drawReportGrid();reportPreview()}
function drawReportGrid(){const x=data.find(a=>a.id===performanceId);if(window.StepUI){StepUI.renderReport(reportYear);return}const months=Array.from({length:12},(_,i)=>`${reportYear}-${String(i+1).padStart(2,'0')}`),active=PlanModel.periodMonths(x.startDate,x.endDate);document.querySelector('#reportGrid').innerHTML=`<div class="annual-scroll"><table class="annual-table"><thead><tr><th>월</th>${months.map((m,i)=>`<th class="${active.includes(m)?'active-month':'inactive-month'}">${i+1}월</th>`).join('')}</tr></thead><tbody><tr><th>누적 목표</th>${months.map(m=>`<td class="${active.includes(m)?'active-cell':'inactive-cell'}">${active.includes(m)?esc(x.monthly[m]?.goal)+'%':'—'}</td>`).join('')}</tr><tr><th>누적 실적</th>${months.map(m=>{const enabled=active.includes(m)&&m<=monthNow();return `<td class="${enabled?'active-cell':'inactive-cell'}"><div class="percent-input"><input data-report-month="${m}" data-report-kind="actual" type="number" min="0" max="100" step="0.1" inputmode="decimal" aria-label="${reportYear}년 ${Number(m.slice(5))}월 누적 실적 (%)" value="${enabled?esc(performanceDraft[m]?.actual??''):''}" ${enabled?'':'disabled'} placeholder="${enabled?'미입력':'—'}" oninput="reportPreview()"><span>%</span></div></td>`}).join('')}</tr></tbody></table></div>`}
function readReport(){if(PlanModel.isWeighted(data.find(a=>a.id===performanceId)))return;if(window.StepUI?.overallSnapshot){performanceDraft=StepUI.overallSnapshot();return;}document.querySelectorAll('[data-report-month]:not(:disabled)').forEach(el=>{performanceDraft[el.dataset.reportMonth]??={};performanceDraft[el.dataset.reportMonth][el.dataset.reportKind]=el.value})}
function reportPreview(){readReport();const x=data.find(a=>a.id===performanceId);if(!x)return;if(window.StepUI){document.querySelector('#reportPreview').textContent=PlanModel.isWeighted(x)?'Step별 실적 입력 후 전체 실적을 비중 합산합니다.':'당월 증가분이 아닌 월말 누적 진척률을 입력합니다.';document.querySelector('#delayReasons').innerHTML='';return}const p=progress({...x,monthly:performanceDraft});document.querySelector('#reportStatus').textContent=p.label;document.querySelector('#reportPreview').textContent=`${p.note} · 각 월의 누적 값을 직접 비교합니다.`;const delayed=PlanModel.periodMonths(x.startDate,x.endDate).filter(m=>m<=monthNow()&&PlanModel.percent(performanceDraft[m]?.actual)!==null&&PlanModel.percent(performanceDraft[m]?.actual)<Number(x.monthly[m].goal));document.querySelector('#delayReasons').innerHTML=delayed.length?`<h3 class="delay-heading">지연 사유 및 Catch Up Plan</h3>${delayed.map(m=>`<div class="delay-card"><strong>${esc(m)} · 목표 ${esc(x.monthly[m].goal)}% / 실적 ${esc(performanceDraft[m].actual)}%</strong><div class="grid"><div class="field"><label for="reason-${m}">지연 사유 *</label><textarea id="reason-${m}" data-report-month="${m}" data-report-kind="reason" oninput="readReport()" placeholder="목표에 미달한 원인을 작성하세요.">${esc(performanceDraft[m]?.reason||'')}</textarea></div><div class="field"><label for="catchup-${m}">Catch Up Plan *</label><textarea id="catchup-${m}" data-report-month="${m}" data-report-kind="catchup" oninput="readReport()" placeholder="만회 방법과 예상 시점을 작성하세요.">${esc(performanceDraft[m]?.catchup||'')}</textarea></div></div></div>`).join('')}`:''}
function savePerformance(){readReport();const x=data.find(a=>a.id===performanceId);if(!x||x.archivedAt)return;const errors=PlanModel.isWeighted(x)?PlanModel.validateStepReports(x,StepUI.reportSnapshot()):PlanModel.validateReports(x,performanceDraft),box=document.querySelector('#reportErrors');box.hidden=!errors.length;if(errors.length){box.innerHTML='<strong>실적 입력을 확인해 주세요.</strong><ul>'+errors.map(e=>`<li>${esc(e.message)}</li>`).join('')+'</ul>';box.scrollIntoView({behavior:'smooth',block:'center'});return}const next=data.map(a=>a.id===performanceId?(PlanModel.isWeighted(a)?StepUI.reportCandidate(a):{...a,monthly:copyObject(performanceDraft)}):a);if(!persistRecords(next))return;render();reportPreview();toast('월별 실적을 저장했습니다.')}
function openPerformance(id){closeModal();showPage('performance');populatePerformance(id)}
document.querySelector('#listPage .top').insertAdjacentHTML('beforeend','<button class="secondary report-shortcut" onclick="showPage(\'performance\')">실적 입력</button>');document.head.insertAdjacentHTML('beforeend',`<style>.report-shortcut{margin-left:8px;white-space:nowrap}.report-info{display:flex;justify-content:space-between;gap:10px;margin:26px 0 10px;align-items:center}.report-info p{font-size:14px;margin-top:5px}.report-info span{font-size:14px;font-weight:700;color:#536fa6}.report-help{font-size:13px;line-height:1.6}.delay-heading{font-size:16px;margin-top:25px}.delay-card{padding:17px;background:#fff8f5;border:1px solid #f1ddd3;border-radius:8px;margin-top:12px}.delay-card>strong{font-size:14px;color:#aa6b49}.delay-card textarea{font-size:14px}.actions{align-items:center}.actions>span{color:#95a1b3;font-size:13px}@media(max-width:800px){#listPage .top{flex-wrap:wrap}.report-shortcut{font-size:12px;padding:10px}}</style>`);
